// ---------- Address bar: star, zoom and suggestions ----------
$('star').onclick=()=>action('bookmark-toggle');$('zoom-pill').onclick=()=>action('zoom-reset');
let suggestItems=[],suggestIndex=-1,suggestSeq=0,suggestTimer;
function hideSuggestions(){suggestItems=[];suggestIndex=-1;$('suggestions').hidden=true;$('suggestions').replaceChildren();$('address').setAttribute('aria-expanded','false');$('address').removeAttribute('aria-activedescendant');}
function placeSuggestions(){const box=$('address-form').getBoundingClientRect(),list=$('suggestions');list.style.left=box.left+'px';list.style.width=box.width+'px';list.style.top=(box.bottom+6)+'px';}
function drawSuggestions(){const list=$('suggestions');list.replaceChildren();suggestItems.forEach((item,i)=>{const li=document.createElement('li');li.id='suggestion-'+i;li.setAttribute('role','option');li.setAttribute('aria-selected',String(i===suggestIndex));li.style.setProperty('--i',i);li.className='suggestion '+item.kind;li.append(icon({search:'search',bookmark:'star',history:'clock',site:'globe',go:'globe'}[item.kind]||'globe'));const text=document.createElement('span');text.className='suggestion-text';const title=document.createElement('strong');title.textContent=item.kind==='search'?item.title:item.title||item.url;const sub=document.createElement('small');sub.textContent=item.kind==='search'?'Search '+item.engine:item.kind==='site'?'HN Group · '+item.url.replace(/^https?:\/\//,''):item.url.replace(/^https?:\/\/(www\.)?/,'');text.append(title,sub);li.append(text);const tag=document.createElement('em');tag.textContent={bookmark:'Bookmark',history:'History',site:'HN shortcut',go:'Go to',search:''}[item.kind]||'';if(tag.textContent)li.append(tag);li.onpointerdown=e=>e.preventDefault();li.onclick=async()=>{suggestSeq++;hideSuggestions();editing=false;await action('panel',null);action('open',{url:item.url});$('address').blur();};list.append(li);});$('address').setAttribute('aria-expanded',String(!!suggestItems.length));if(suggestIndex>=0)$('address').setAttribute('aria-activedescendant','suggestion-'+suggestIndex);else $('address').removeAttribute('aria-activedescendant');}
$('address').addEventListener('input',()=>{clearTimeout(suggestTimer);const text=$('address').value,seq=++suggestSeq;suggestIndex=-1;if(!text.trim()||current?.preferences?.suggestions===false||(current?.panel&&current.panel!=='suggest')){if(current?.panel==='suggest')action('panel',null);hideSuggestions();return;}
 suggestTimer=setTimeout(async()=>{const r=await window.browser.action('suggest',text);if(seq!==suggestSeq||document.activeElement!==$('address'))return;suggestItems=r.result||[];if(!suggestItems.length){hideSuggestions();if(current?.panel==='suggest')action('panel',null);return;}if(current?.panel!=='suggest')await window.browser.action('panel','suggest');if(seq!==suggestSeq||document.activeElement!==$('address'))return;placeSuggestions();drawSuggestions();$('suggestions').hidden=false;},70);});
$('address').addEventListener('keydown',e=>{if(!suggestItems.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();suggestIndex=(suggestIndex+(e.key==='ArrowDown'?1:-1)+suggestItems.length+1)%(suggestItems.length+1);if(suggestIndex===suggestItems.length)suggestIndex=-1;drawSuggestions();}else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();suggestSeq++;hideSuggestions();action('panel',null);}});
addEventListener('resize',()=>{if(!$('suggestions').hidden)placeSuggestions();});

// ---------- Bookmarks bar ----------
let barKey='';
function renderBookmarkBar(state){const list=state.bookmarks||[],key=list.map(b=>b.id+b.title+b.url).join('|');if(key===barKey)return;barKey=key;const bar=$('user-bookmarks');bar.replaceChildren();for(const b of list.slice(0,30)){const button=document.createElement('button');button.className='user-bookmark';button.title=b.title+'\n'+b.url;const letter=document.createElement('b');letter.textContent=(b.title.trim()[0]||'•').toUpperCase();button.append(letter,document.createTextNode(b.title));button.onclick=()=>action('open',{url:b.url});button.onauxclick=e=>{if(e.button===1){e.preventDefault();action('open',{url:b.url,newTab:true,background:true});}};button.oncontextmenu=e=>{e.preventDefault();action('bookmark-menu',b.id);};bar.append(button);}}

// ---------- History page ----------
let historyTimer;
function dayLabel(time){const d=new Date(time),today=new Date();today.setHours(0,0,0,0);const diff=Math.round((today-new Date(d).setHours(0,0,0,0))/86400000);return diff===0?'Today':diff===1?'Yesterday':d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',...(d.getFullYear()!==today.getFullYear()?{year:'numeric'}:{})});}
async function loadHistory(){const query=$('history-search').value,r=await window.browser.action('history-list',query);const items=r.result||[],list=$('history-list');list.replaceChildren();let day='';
 $('history-off').hidden=current?.preferences?.saveHistory!==false;$('history-empty').hidden=!!items.length;$('history-empty-title').textContent=query?'No matching pages.':'Nothing here yet.';$('history-empty-text').textContent=query?'Try a different word or website.':'Websites you visit will appear here.';$('history-summary').textContent=items.length?(query?items.length+' matching page'+(items.length===1?'':'s'):'Pages you’ve visited in HN Browser on this device.'):'Pages you’ve visited in HN Browser on this device.';
 items.forEach((e,i)=>{const label=dayLabel(e.time);if(label!==day){day=label;const h=document.createElement('h2');h.className='library-day';h.textContent=label;list.append(h);}const row=document.createElement('article');row.className='library-row';row.style.setProperty('--i',Math.min(i,20));const time=document.createElement('time');time.textContent=new Date(e.time).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});const letter=document.createElement('b');letter.className='site-letter';letter.textContent=((e.title||e.url.replace(/^https?:\/\/(www\.)?/,'')).trim()[0]||'•').toUpperCase();const open=document.createElement('button');open.className='library-open';const title=document.createElement('strong');title.textContent=e.title||e.url;const sub=document.createElement('small');sub.textContent=e.url.replace(/^https?:\/\/(www\.)?/,'');open.append(title,sub);open.onclick=()=>action('open',{url:e.url});open.onauxclick=ev=>{if(ev.button===1){ev.preventDefault();action('open',{url:e.url,newTab:true,background:true});}};
 const tools=document.createElement('div');tools.className='row-tools';const newTab=document.createElement('button');newTab.append(icon('plus'));newTab.title='Open in new tab';newTab.setAttribute('aria-label','Open '+(e.title||e.url)+' in a new tab');newTab.onclick=()=>action('open',{url:e.url,newTab:true,background:true});const remove=document.createElement('button');remove.append(icon('trash'));remove.title='Remove from history';remove.setAttribute('aria-label','Remove '+(e.title||e.url)+' from history');remove.onclick=async()=>{row.classList.add('leaving');await action('history-remove',e.id);setTimeout(loadHistory,motion()?180:0);};tools.append(newTab,remove);row.append(time,letter,open,tools);list.append(row);});}
$('history-search').oninput=()=>{clearTimeout(historyTimer);historyTimer=setTimeout(loadHistory,150);};$('history-clear').onclick=async()=>{const r=await action('history-clear',$('history-range').value);if(r.result)loadHistory();};

// ---------- Bookmarks page ----------
function renderBookmarks(){const query=$('bookmark-search').value.trim().toLowerCase(),all=current?.bookmarks||[],items=all.filter(b=>!query||b.title.toLowerCase().includes(query)||b.url.toLowerCase().includes(query)),list=$('bookmarks-list');
 if(list.contains(document.activeElement)&&document.activeElement.matches('input'))return;
 $('bookmarks-empty').hidden=!!all.length;$('bookmarks-summary').textContent=all.length?all.length+' bookmark'+(all.length===1?'':'s')+' · the first 30 appear in the bookmarks bar.':'Favourite places, one click away in the bookmarks bar.';const t=current?.tabs.find(x=>x.id===current.active);$('bookmark-current').disabled=!t||!/^https?:/.test(t.url)||all.some(b=>b.url===t.url);
 const key=items.map(b=>b.id+b.title).join('|');if(list.dataset.key===key)return;list.dataset.key=key;list.replaceChildren();
 items.forEach((b,i)=>{const row=document.createElement('article');row.className='library-row bookmark-row';row.style.setProperty('--i',Math.min(i,20));const letter=document.createElement('b');letter.className='site-letter';letter.textContent=(b.title.trim()[0]||'•').toUpperCase();const open=document.createElement('button');open.className='library-open';const title=document.createElement('strong');title.textContent=b.title;const sub=document.createElement('small');sub.textContent=b.url.replace(/^https?:\/\/(www\.)?/,'');open.append(title,sub);open.onclick=()=>action('open',{url:b.url});
  const tools=document.createElement('div');tools.className='row-tools';const make=(symbol,label,fn)=>{const x=document.createElement('button');x.append(icon(symbol));x.title=label;x.setAttribute('aria-label',label+': '+b.title);x.onclick=fn;tools.append(x);return x;};
  make('edit','Rename',()=>{const input=document.createElement('input');input.className='rename';input.value=b.title;input.maxLength=120;input.setAttribute('aria-label','Bookmark name');open.replaceWith(input);input.focus();input.select();let done=false;const finish=async save=>{if(done)return;done=true;if(save&&input.value.trim()&&input.value.trim()!==b.title)await action('bookmark-rename',{id:b.id,title:input.value});list.dataset.key='';input.blur();renderBookmarks();};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();finish(true);}else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();finish(false);}};input.onblur=()=>finish(true);});
  make('arrow-up','Move up',()=>action('bookmark-move',{id:b.id,step:-1})).disabled=query!==''||i===0;make('arrow-down','Move down',()=>action('bookmark-move',{id:b.id,step:1})).disabled=query!==''||i===items.length-1;
  make('trash','Remove',async()=>{row.classList.add('leaving');setTimeout(()=>action('bookmark-remove',b.id),motion()?170:0);});
  row.append(letter,open,tools);list.append(row);});}
$('bookmark-search').oninput=()=>{$('bookmarks-list').dataset.key='';renderBookmarks();};$('bookmark-current').onclick=()=>action('bookmark-toggle');

// ---------- Your profile (Settings) ----------
// The profile is read from HN Group when this section opens; changes go to the staff portal through Auth.
let profile=null,loadingProfile=false;
const STATUS_LABELS={available:'Available',busy:'Busy',away:'Away',ooo:'Out of office'};
for(const zone of [...new Set(['Europe/London',...(Intl.supportedValuesOf?.('timeZone')||[]),'UTC'])]){const option=document.createElement('option');option.value=zone;option.textContent=zone.replace(/_/g,' ');$('pf-timezone').append(option);}
for(let d=1;d<=31;d++){const o=document.createElement('option');o.value=String(d);o.textContent=String(d);document.querySelector('[name=birthdayDay]').append(o);}
['January','February','March','April','May','June','July','August','September','October','November','December'].forEach((m,i)=>{const o=document.createElement('option');o.value=String(i+1);o.textContent=m;document.querySelector('[name=birthdayMonth]').append(o);});
function renderProfileGate(state){const ready=!!state.user,editor=$('profile-editor');$('profile-gate').hidden=ready&&!!profile;editor.hidden=!(ready&&profile);
 if(!ready){profile=null;$('profile-gate-title').textContent=state.locked?'Unlock to manage your profile':'Sign in to manage your profile';$('profile-gate-text').textContent=state.locked?'Your HN Group profile can be changed here once HN Browser is unlocked with your PIN.':'Sign in to HN Browser with your HN Group account to see and change your profile here.';$('profile-gate-button').textContent=state.locked?'Unlock HN Browser':'Sign in to HN Group';$('profile-gate-button').dataset.do='account';}
 else if(!profile){$('profile-gate-title').textContent=loadingProfile?'Loading your profile…':'Your profile';$('profile-gate-text').textContent=loadingProfile?'Getting your details from HN Group.':$('profile-gate-text').dataset.error||'Open your profile to see and change it.';$('profile-gate-button').textContent=$('profile-gate-text').dataset.relock?'Lock and unlock with your PIN':'Try again';$('profile-gate-button').dataset.do=$('profile-gate-text').dataset.relock?'relock':'load';$('profile-gate-button').hidden=loadingProfile;}}
$('profile-gate-button').onclick=async()=>{const what=$('profile-gate-button').dataset.do;if(what==='account')action('panel','account');else if(what==='relock')action('lock');else loadProfile();};
async function loadProfile(){if(!current?.user||loadingProfile)return;loadingProfile=true;delete $('profile-gate-text').dataset.error;delete $('profile-gate-text').dataset.relock;renderProfileGate(current);const r=await window.browser.action('account-get');loadingProfile=false;if(r.error){profile=null;$('profile-gate-text').dataset.error=r.error;if(r.relock)$('profile-gate-text').dataset.relock='1';}else fillProfile(r.result);renderProfileGate(current);}
function fillProfile(p){if(!p)return;profile=p;const f=$('profile-form');f.displayName.value=p.displayName;f.phone.value=p.phone;f.location.value=p.location;if(p.timezone&&![...f.timezone.options].some(o=>o.value===p.timezone)){const o=document.createElement('option');o.value=o.textContent=p.timezone;f.timezone.prepend(o);}f.timezone.value=p.timezone||'Europe/London';f.skills.value=(p.skills||[]).join(', ');f.languages.value=(p.languages||[]).join(', ');f.bio.value=p.bio||'';f.bioPublic.checked=p.bioPublic!==false;f.birthdayDay.value=p.birthday?String(p.birthday.day):'';f.birthdayMonth.value=p.birthday?String(p.birthday.month):'';f.showBirthday.checked=!!p.birthday?.show;$('pf-bio-count').textContent=f.bio.value.length+' / 600';
 $('settings-account-name').textContent=p.displayName;$('pf-meta').textContent=[p.jobTitle,p.company].filter(Boolean).join(' · ')||p.email;$('pf-photo-remove').hidden=!p.photo;
 const details=[['Email',p.email],['Name on formal records',[p.firstName,p.lastName].filter(Boolean).join(' ')],['Job title',p.jobTitle],['Company',p.company],['Department',p.department],['Manager',p.supervisor],['Roles',(p.roles||[]).join(', ')],['Last signed in',p.lastLogin?new Date(p.lastLogin).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'']].filter(([,v])=>v);$('pf-details').replaceChildren(...details.flatMap(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;return[dt,dd];}));
 setStatusChoice(p.status?.type||'');$('st-message').value=p.status?.message||'';$('st-until').value=p.status?.until||'';markClean();}
let statusChoice='';function setStatusChoice(type){statusChoice=type;for(const b of document.querySelectorAll('[data-status]'))b.setAttribute('aria-checked',String(b.dataset.status===type));$('st-message').disabled=$('st-until').disabled=!type;}
for(const b of document.querySelectorAll('[data-status]'))b.onclick=()=>setStatusChoice(b.dataset.status);
const tags=value=>value.split(',').map(s=>s.trim()).filter(Boolean);
function profileInput(){const f=$('profile-form');return{displayName:f.displayName.value.trim(),phone:f.phone.value.trim(),location:f.location.value.trim(),timezone:f.timezone.value,skills:tags(f.skills.value),languages:tags(f.languages.value),bio:f.bio.value,bioPublic:f.bioPublic.checked,birthdayDay:f.birthdayDay.value,birthdayMonth:f.birthdayMonth.value,showBirthday:f.showBirthday.checked};}
let cleanInput='';function markClean(){cleanInput=JSON.stringify(profileInput());$('profile-form').classList.remove('dirty');}
$('profile-form').addEventListener('input',()=>{$('profile-form').classList.toggle('dirty',JSON.stringify(profileInput())!==cleanInput);$('pf-bio-count').textContent=$('profile-form').bio.value.length+' / 600';$('pf-saved').textContent='';});
$('pf-reset').onclick=()=>{fillProfile(profile);$('pf-saved').textContent='';};
