$('profile-form').onsubmit=async e=>{e.preventDefault();const input=profileInput();if(!input.displayName){flash('pf-saved','Add a display name.');$('profile-form').displayName.focus();return;}if((input.birthdayDay&&!input.birthdayMonth)||(!input.birthdayDay&&input.birthdayMonth)){flash('pf-saved','Choose both a day and a month for your birthday.');return;}const button=e.submitter||$('profile-form').querySelector('[type=submit]');button.disabled=true;flash('pf-saved','Saving…');const r=await action('account-update',input);button.disabled=false;if(r.error){flash('pf-saved',r.error);if(r.relock){profile=null;$('profile-gate-text').dataset.error=r.error;$('profile-gate-text').dataset.relock='1';renderProfileGate(current);}return;}fillProfile(r.result);flash('pf-saved','Saved ✓');};
$('status-form').onsubmit=async e=>{e.preventDefault();const status=statusChoice?{type:statusChoice,message:$('st-message').value.trim(),until:$('st-until').value||null}:null;flash('st-saved','Saving…');const r=await action('account-status',status);if(r.error){flash('st-saved',r.error);return;}fillProfile(r.result);flash('st-saved','Updated ✓');};
$('pf-photo-change').onclick=async()=>{const r=await action('account-photo','choose');if(r.result)fillProfile(r.result);};$('pf-photo-remove').onclick=async()=>{const r=await action('account-photo','remove');if(r.result)fillProfile(r.result);};
