// ---------- Keyboard shortcuts list ----------
function renderShortcuts(mac){const m=mac?'⌘':'Ctrl',list=[['New tab',m+' T'],['Close tab',m+' W'],['Reopen closed tab',m+' ⇧ T'],['Next / previous tab','Ctrl Tab / Ctrl ⇧ Tab'],['Go to tab 1–8 / last tab',m+' 1–8 / '+m+' 9'],['Address bar',m+' L'],['Find in page',m+' F'],['Bookmark this page',m+' D'],['Bookmarks',m+' ⇧ O'],['Show or hide bookmarks bar',m+' ⇧ B'],['History',mac?'⌘ Y':'Ctrl H'],['Downloads',m+' J'],['Settings',m+' ,'],['HN VPN',m+' ⇧ V'],['Print',m+' P'],['Lock HN Browser',m+' ⇧ L'],['Reload',m+' R / F5'],['Back / forward',mac?'⌘ [ / ⌘ ]':'Alt ← / Alt →'],['Zoom in / out / reset',m+' + / '+m+' − / '+m+' 0'],['Close a menu','Esc']];$('shortcut-list').replaceChildren(...list.flatMap(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;for(const part of v.split(' / ')){const kbd=document.createElement('kbd');kbd.textContent=part;dd.append(kbd);}return[dt,dd];}));}
